import sys
from collections import defaultdict, deque

def find(u, parent):
    if parent[u] != u:
        parent[u] = find(parent[u], parent)
    return parent[u]

def union(u, v, parent, rank):
    rootU = find(u, parent)
    rootV = find(v, parent)
    if rootU != rootV:
        if rank[rootU] > rank[rootV]:
            parent[rootV] = rootU
        elif rank[rootU] < rank[rootV]:
            parent[rootU] = rootV
        else:
            parent[rootV] = rootU
            rank[rootU] += 1

def bfs(start, adj_list, n):
    visited = [False] * (n + 1)
    queue = deque([start])
    visited[start] = True
    while queue:
        node = queue.popleft()
        for neighbor in adj_list[node]:
            if not visited[neighbor]:
                visited[neighbor] = True
                queue.append(neighbor)
    return visited

def main():
    import sys
    input = sys.stdin.read().split()
    index = 0
    n = int(input[index])
    index += 1
    T1_edges = []
    for _ in range(n - 1):
        a = int(input[index])
        b = int(input[index + 1])
        T1_edges.append((a, b))
        index += 2
    T2_edges = []
    for _ in range(n - 1):
        c = int(input[index])
        d = int(input[index + 1])
        T2_edges.append((c, d))
        index += 2

    parent = list(range(n + 1))
    rank = [0] * (n + 1)
    adj_list_T1 = defaultdict(list)
    for a, b in T1_edges:
        adj_list_T1[a].append(b)
        adj_list_T1[b].append(a)
        union(a, b, parent, rank)

    matches = {}
    for c, d in T2_edges:
        temp_parent = parent[:]
        temp_rank = rank[:]
        union(c, d, temp_parent, temp_rank)
        visited = bfs(c, adj_list_T1, n)
        if all(visited[1:]):
            for a, b in T1_edges:
                if find(a, temp_parent) != find(b, temp_parent):
                    if (a, b) not in matches and (b, a) not in matches:
                        matches[(a, b)] = (c, d)
                        break

    print(len(matches))
    for (a, b), (c, d) in matches.items():
